ROM c.`ProcessingFee`, 'ProcessingFee', NULL),IF(b.`ProcessingFeeVat` IS DISTINCT FROM c.`ProcessingFeeVat`, 'ProcessingFeeVat', NULL),IF(b.`ShippingFee` IS DISTINCT FROM c.`ShippingFee`, 'ShippingFee', NULL),IF(b.`ShippingFeeVat` IS DISTINCT FROM c.`ShippingFeeVat`, 'ShippingFeeVat', NULL),IF(b.`TotalAmount` IS DISTINCT FROM c.`TotalAmount`, 'TotalAmount', NULL),IF(b.`Discount` IS DISTINCT FROM c.`Discount`, 'Discount', NULL),IF(b.`TransactionStatus` IS DISTINCT FROM c.`TransactionStatus`, 'TransactionStatus', NULL),IF(b.`SubmissionStatus` IS DISTINCT FROM c.`SubmissionStatus`, 'SubmissionStatus', NULL),IF(b.`ApprovalStatus` IS DISTINCT FROM c.`ApprovalStatus`, 'ApprovalStatus', NULL),IF(b.`PaymentStatus` IS DISTINCT FROM c.`PaymentStatus`, 'PaymentStatus', NULL),IF(b.`ExpectedReceived` IS DISTINCT FROM c.`ExpectedReceived`, 'ExpectedReceived', NULL),IF(b.`ActualReceived` IS DISTINCT FROM c.`ActualReceived`, 'ActualReceived', NULL),IF(b.`InterestThisPeriod` IS DISTINCT FROM c.`InterestThisPeriod`, 'InterestThisPeriod', NULL),IF(b.`PrincipleThisPeriod` IS DISTINCT FROM c.`PrincipleThisPeriod`, 'PrincipleThisPeriod', NULL),IF(b.`InterestEIRThisPeriod` IS DISTINCT FROM c.`InterestEIRThisPeriod`, 'InterestEIRThisPeriod', NULL),IF(b.`PrincipleEIRThisPeriod` IS DISTINCT FROM c.`PrincipleEIRThisPeriod`, 'PrincipleEIRThisPeriod', NULL),IF(b.`PaymentDate` IS DISTINCT FROM c.`PaymentDate`, 'PaymentDate', NULL),IF(b.`Period` IS DISTINCT FROM c.`Period`, 'Period', NULL),IF(b.`TotalPeriods` IS DISTINCT FROM c.`TotalPeriods`, 'TotalPeriods', NULL),IF(b.`PendingPayment` IS DISTINCT FROM c.`PendingPayment`, 'PendingPayment', NULL),IF(b.`PaymentMethod` IS DISTINCT FROM c.`PaymentMethod`, 'PaymentMethod', NULL),IF(b.`PaymentChannel` IS DISTINCT FROM c.`PaymentChannel`, 'PaymentChannel', NULL),IF(b.`ExpectedDate` IS DISTINCT FROM c.`ExpectedDate`, 'ExpectedDate', NULL),IF(b.`RefOrder` IS DISTINCT FROM c.`RefOrder`, 'RefOrder', NULL),IF(b.`RefundAmountBeforeFee` IS DISTINCT FROM c.`Re